def calculate_a(n_max):
    a = {}
    a[1] = 1
    a[2] = 1

    for n in range(3, n_max + 1):
        # a_n = a_{a_{n-1}} + a_{n - a_{n-1}}

        # Need a_{n-1} first
        if n - 1 not in a:
            # Should not happen if we iterate sequentially
            raise ValueError(f"Missing a_{n-1}")

        a_n_minus_1 = a[n - 1]

        # Need a_{a_{n-1}}
        idx1 = a_n_minus_1
        if idx1 not in a:
            # This means the value of a_{n-1} is too large, recursion depth exceeded or not calculated yet.
            # Since a_n is positive, idx1 >= 1.
            print(f"Error: a_{idx1} not computed when calculating a_{n} for n={n}")
            return None

        val1 = a[idx1]

        # Need a_{n - a_{n-1}}
        idx2 = n - a_n_minus_1
        if idx2 <= 0 or idx2 not in a:
            # idx2 must be positive. Since a_{n-1} >= 1, n - a_{n-1} < n-1. 
            # If a_{n-1} > n-1, then idx2 <= 0.
            if idx2 <= 0:
                 print(f"Error: Index {idx2} for a_{n} is non-positive.")
                 return None
            else:
                 print(f"Error: a_{idx2} not computed when calculating a_{n} for n={n}")
                 return None

        val2 = a[idx2]

        a[n] = val1 + val2

    return a

# Calculate up to n=20 to check initial patterns
